<template><van-popup v-model:show="visible" position="bottom" round class="figma-date-popup"><header><h2>日期选择</h2><button type="button" @click="visible=false"><van-icon name="cross"/></button></header><van-calendar :poppable="false" :show-title="false" show-subtitle show-confirm confirm-text="确认" color="#00AAA6" @confirm="handleConfirm"/></van-popup></template>
<script setup>import{computed}from'vue';const props=defineProps({show:Boolean});const emit=defineEmits(['update:show','confirm']);const visible=computed({get:()=>props.show,set:v=>emit('update:show',v)});function handleConfirm(date){emit('confirm',date);visible.value=false}</script>
<style scoped>.figma-date-popup{overflow:hidden;background:#fff}.figma-date-popup header{position:relative;height:52px;display:flex;align-items:center;justify-content:center}.figma-date-popup h2{margin:0;color:#1D2129;font:600 14px/20px "PingFang SC",sans-serif}.figma-date-popup header button{position:absolute;top:4px;right:8px;width:44px;height:44px;border:0;color:#86909C;background:transparent;font-size:18px}.figma-date-popup :deep(.van-calendar__header){box-shadow:none}.figma-date-popup :deep(.van-calendar__header-subtitle){color:#1D2129;font-size:14px;font-weight:600}.figma-date-popup :deep(.van-calendar__weekday){color:#4E5969;font-size:12px}.figma-date-popup :deep(.van-calendar__day){height:48px;color:#4E5969;font-size:14px;line-height:48px}.figma-date-popup :deep(.van-calendar__day--selected){width:36px;height:38px;margin:5px auto;border-radius:4px;color:#fff!important;background:#00AAA6!important;line-height:38px}.figma-date-popup :deep(.van-calendar__footer){padding:12px}.figma-date-popup :deep(.van-calendar__confirm){height:44px;border-radius:20px;background:#22BBB3}</style>
